def parse_query_string(query):

    params = {}

    pairs = (part.split('=', 1) for part in filter(None, map(str.strip, query.lstrip('?').split('&'))))

    [params[key] if key else None].extend(value or [] for _, value in pairs)

    return dict(filter(lambda item: not isinstance(item[0], str), params.items()))


# Example usage:

query_string = 'foo=1&bar hello'

parsed_query = parse_query_string(query_string)
print(parsed_query)  # Output will be {'': ['hello'], foo: [None]}

```

